package com.servicerca.controller;import com.servicerca.dto.notification.PushSubscriptionRequest;import com.servicerca.security.SecurityUser;import com.servicerca.service.NotificationService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/notifications/subscriptions")public class NotificationController{private final NotificationService service;public NotificationController(NotificationService s){service=s;}@PostMapping public ResponseEntity<Void>subscribe(@AuthenticationPrincipal SecurityUser u,@Valid@RequestBody PushSubscriptionRequest r){service.subscribe(u.user(),r);return ResponseEntity.noContent().build();}@DeleteMapping public ResponseEntity<Void>unsubscribe(@RequestParam String endpoint){service.unsubscribe(endpoint);return ResponseEntity.noContent().build();}}
